29: // tiff_info.cpp
30: // =============
31: // A simple program to print TIFF image metadata and IFD entries.
32: //
33: // Usage: tiff_info <image.tiff> [--tags]
34: //
35: 
36: #include <tiffcraft/TiffStdOut.hpp>
37: 
38: #include <cstddef>
39: #include <cstdint>
40: #include <exception>
41: #include <iostream>
42: #include <string>
43: #include <vector>
44: 
45: namespace {
46: 
47:   using TiffCraft::Tag;
48:   using TiffCraft::Type;
49:   using TiffCraft::TiffImage;
50: 
51:   // Read the first integer value of an entry without assuming its TIFF type.
52:   bool firstValue(const TiffImage::IFD& ifd, Tag tag, std::uint32_t& out) {
53:     if (!ifd.entries().contains(tag)) {
54:       return false;
55:     }
56:     const auto& entry = ifd.getEntry(tag);
57:     switch (entry.type()) {
58:       case Type::SHORT:
59:         out = entry.values<std::uint16_t>()[0];
60:         return true;
61:       case Type::LONG:
62:         out = entry.values<std::uint32_t>()[0];
63:         return true;
64:       default:
65:         return false;
66:     }
67:   }
68: 
69:   std::string firstValueString(const TiffImage::IFD& ifd, Tag tag) {
70:     std::uint32_t value = 0;
71:     if (!firstValue(ifd, tag, value)) {
72:       return "n/a";
73:     }
74:     return std::to_string(value);
75:   }
76: 
77:   // Some tags (e.g. BitsPerSample) hold one value per sample.
78:   std::string allValuesString(const TiffImage::IFD& ifd, Tag tag) {
79:     if (!ifd.entries().contains(tag)) {
80:       return "n/a";
81:     }
82:     const auto& entry = ifd.getEntry(tag);
83:     std::string result;
84:     const auto append = [&result](std::uint32_t value) {
85:       if (!result.empty()) {
86:         result += ", ";
87:       }
88:       result += std::to_string(value);
89:     };
90:     switch (entry.type()) {
91:       case Type::SHORT:
92:         for (const auto value : entry.values<std::uint16_t>()) {
93:           append(value);
94:         }
95:         break;
96:       case Type::LONG:
97:         for (const auto value : entry.values<std::uint32_t>()) {
98:           append(value);
99:         }
100:         break;
101:       default:
102:         return "n/a";
103:     }
104:     return result.empty() ? "n/a" : result;
105:   }
106: 
107:   std::string layoutString(const TiffImage::IFD& ifd) {
108:     if (ifd.entries().contains(Tag::TileOffsets)) {
109:       return "tiles (count " + std::to_string(ifd.getEntry(Tag::TileOffsets).count()) + ")";
110:     }
111:     if (ifd.entries().contains(Tag::StripOffsets)) {
112:       return "strips (count " + std::to_string(ifd.getEntry(Tag::StripOffsets).count()) + ")";
113:     }
114:     return "n/a";
115:   }
116: 
117:   std::string totalBytesString(const TiffImage::IFD& ifd) {
118:     Tag countTag = Tag::Null;
119:     if (ifd.entries().contains(Tag::StripByteCounts)) {
120:       countTag = Tag::StripByteCounts;
121:     } else if (ifd.entries().contains(Tag::TileByteCounts)) {
122:       countTag = Tag::TileByteCounts;
123:     }
124:     if (countTag == Tag::Null) {
125:       return "n/a";
126:     }
127: 
128:     const auto& entry = ifd.getEntry(countTag);
129:     std::uint64_t total = 0;
130:     switch (entry.type()) {
131:       case Type::SHORT:
132:         for (const auto value : entry.values<std::uint16_t>()) {
133:           total += value;
134:         }
135:         break;
136:       case Type::LONG:
137:         for (const auto value : entry.values<std::uint32_t>()) {
138:           total += value;
139:         }
140:         break;
141:       default:
142:         return "n/a";
143:     }
144:     return std::to_string(total);
145:   }
146: 
147: } // namespace
148: 
149: int main(int argc, char* argv[]) {
150:   if (argc < 2) {
151:     std::cerr << "Usage: " << argv[0] << " <image.tiff> [--tags]\n";
152:     return 1;
153:   }
154: 
155:   const std::string input_file = argv[1];
156:   const bool showTags = (argc > 2 && std::string(argv[2]) == "--tags");
157: 
158:   try {
159:     // read() exposes the header and IFD entries without decoding pixel data.
160:     TiffCraft::TiffImage image = TiffCraft::TiffImage::read(input_file);
161: 
162:     std::cout << "File: " << input_file << "\n";
163:     std::cout << "TiffCraft version " << TiffCraft::version() << "\n";
164:     std::cout << image.header();
165: 
166:     std::size_t ifdIndex = 0;
167:     for (const auto& ifd : image.ifds()) {
168:       std::cout << "IFD " << ifdIndex++ << ":\n";
169: 
170:       if (showTags) {
171:         std::cout << "Entry count: " << ifd.entries().size() << "\n";
172:         for (const auto& item : ifd.entries()) {
173:           std::cout << item.second;
174:         }
175:       } else {
176:         std::cout << "  Image width: " << firstValueString(ifd, Tag::ImageWidth) << "\n";
177:         std::cout << "  Image height: " << firstValueString(ifd, Tag::ImageLength) << "\n";
178:         std::cout << "  Samples per pixel: " << firstValueString(ifd, Tag::SamplesPerPixel) << "\n";
179:         std::cout << "  Bits per sample: " << allValuesString(ifd, Tag::BitsPerSample) << "\n";
180:         std::cout << "  Photometric interpretation: "
181:                   << firstValueString(ifd, Tag::PhotometricInterpretation) << "\n";
182:         std::cout << "  Compression: " << firstValueString(ifd, Tag::Compression) << "\n";
183:         std::cout << "  Planar configuration: "
184:                   << firstValueString(ifd, Tag::PlanarConfiguration) << "\n";
185:         std::cout << "  Strip/tile info: " << layoutString(ifd) << "\n";
186:         std::cout << "  Total image data bytes: " << totalBytesString(ifd) << "\n";
187:       }
188:     }
189:   }
190:   catch (const std::exception& ex) {
191:     std::cerr << "Error: " << ex.what() << "\n";
192:     return 1;
193:   }
194: 
195:   return 0;
196: }

