82: TEST_CASE("operator<< streams Header, Entry, IFD, and TiffImage") {
83:   const auto path = std::filesystem::path(__FILE__).parent_path()
84:     / "libtiff-pics" / "pc260001.tif";
85:   REQUIRE_MESSAGE(std::filesystem::exists(path),
86:     "Test image fixture is missing: ", path.string());
87: 
88:   const TiffImage image = TiffImage::read(path.string());
89: 
90:   std::ostringstream headerStream;
91:   headerStream << image.header();
92:   CHECK(contains(headerStream.str(), "TIFF Header:"));
93:   CHECK(contains(headerStream.str(), "Byte Order"));
94:   CHECK(contains(headerStream.str(), "First IFD Offset"));
95:   CHECK(contains(headerStream.str(), "Equals Host Byte Order"));
96: 
97:   REQUIRE(!image.ifds().empty());
98:   const auto& ifd = image.ifds().front();
99: 
100:   std::ostringstream entryStream;
101:   REQUIRE(!ifd.entries().empty());
102:   const auto& entry = ifd.entries().begin()->second;
103:   entryStream << entry;
104:   CHECK(contains(entryStream.str(), "Tag:"));
105:   CHECK(contains(entryStream.str(), "Type:"));
106:   CHECK(contains(entryStream.str(), "Count:"));
107:   CHECK(contains(entryStream.str(), "Value:"));
108: 
109:   std::ostringstream ifdStream;
110:   ifdStream << ifd;
111:   CHECK(contains(ifdStream.str(), "TIFF IFD:"));
112:   CHECK(contains(ifdStream.str(), "Entry count:"));
113: 
114:   std::ostringstream imageStream;
115:   imageStream << image;
116:   CHECK(contains(imageStream.str(), "TIFF IMAGE START"));
117:   CHECK(contains(imageStream.str(), "TIFF IMAGE END"));
118: }
